function recolorShell(screen, color){
  const sb=screen.children.find(c=>c.name==='Status Bar');
  if(!sb) return;
  function walk(n){
    for(const ch of n.children){ 
      if(ch.type==='TEXT'){ ch.fills=[{type:'SOLID',color}]; }
      else if(ch.fills && ch.fills.length && ch.fills[0].type==='SOLID' && ch.name!=='Dynamic Island'){ ch.fills=[{type:'SOLID',color}]; }
      if('children' in ch) walk(ch);
    }
  }
  walk(sb);
}

