function rr(p,name,x,y,w,h,fill,rad){const r=figma.createRectangle();r.name=name;r.x=Math.round(x);r.y=Math.round(y);r.resize(Math.round(w),Math.round(h));r.fills=[{type:'SOLID',color:fill}];if(rad)r.cornerRadius=rad;p.appendChild(r);return r;}
function ell(p,name,x,y,w,h,fill){const e=figma.createEllipse();e.name=name;e.x=Math.round(x);e.y=Math.round(y);e.resize(Math.round(w),Math.round(h));e.fills=[{type:'SOLID',color:fill}];p.appendChild(e);return e;}
function walkColor(n,color){for(const ch of n.children){if(ch.type==='TEXT'){ch.fills=[{type:'SOLID',color}];}else if(ch.fills&&ch.fills.length&&ch.fills[0].type==='SOLID'&&ch.name!=='Dynamic Island'){ch.fills=[{type:'SOLID',color}];}if('children' in ch)walkColor(ch,color);}}
function addShell(fr){const sb=figma.getNodeById('1:33').clone();sb.name='Status Bar';sb.x=0;sb.y=0;fr.appendChild(sb);const hi=figma.getNodeById('1:44').clone();hi.name='Home Indicator';hi.x=0;hi.y=818;fr.appendChild(hi);}

